import{_ as a,o as n,c as t,a0 as l}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"Object.prototype.toString()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Object/toString.md","filePath":"jsApi/Object/toString.md","lastUpdated":1791573371000}'),e={name:"jsApi/Object/toString.md"};function o(p,s,r,c,i,d){return n(),t("div",null,[...s[0]||(s[0]=[l(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Object/toString" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/toString" target="_blank">en</a></p><h1 id="object-prototype-tostring" tabindex="-1">Object.prototype.toString() <a class="header-anchor" href="#object-prototype-tostring" aria-label="Permalink to &quot;Object.prototype.toString()&quot;">​</a></h1><p>toString() 方法返回一个表示该对象的字符串。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">object.</span><span style="color:#6F42C1;">toString</span><span style="color:#24292E;">()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h3><p>一个表示该对象的字符串</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>每个对象都有一个 toString() 方法，当对象被表示为文本值时或者当以期望字符串的方式引用对象时，该方法被自动调用。默认情况下， toString() 方法被每个继承自Object的对象继承。如果此方法在自定义对象中未被覆盖，toString() 返回 &quot;[object type]&quot;,其中type 是对象类型。以下代码说明了这一点：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> o </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Object</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#24292E;">o.</span><span style="color:#6F42C1;">toString</span><span style="color:#24292E;">();           </span><span style="color:#6A737D;">// 返回了[object Object]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>Note: 从JavaScript 1.8.5开始，用null调用toString()方法会返回[object Null]，类似的用undefined调用会返回[object Undefined], 如在ECMAScript的第5版中定义的和后续的勘误表。查看使用toString方法检测对象类型一文了解详情.</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="覆盖默认的tostring方法" tabindex="-1">覆盖默认的toString方法 <a class="header-anchor" href="#覆盖默认的tostring方法" aria-label="Permalink to &quot;覆盖默认的toString方法&quot;">​</a></h3><p>可以自定义一个方法来取代默认的 toString() 方法。该 toString() 方法不能传入参数并且必须返回一个字符串。自定义的 toString() 方法可以是任何我们需要的值，但如果它附带有关对象的信息，它将变的非常有用。</p><p>在下面的代码中，定义了一个 Dog 对象数据类型，并且创建了该对象的一个实例：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> Dog</span><span style="color:#24292E;">(</span><span style="color:#E36209;">name</span><span style="color:#24292E;">,</span><span style="color:#E36209;">breed</span><span style="color:#24292E;">,</span><span style="color:#E36209;">color</span><span style="color:#24292E;">,</span><span style="color:#E36209;">sex</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#005CC5;">   this</span><span style="color:#24292E;">.name</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">name;</span></span>
<span class="line"><span style="color:#005CC5;">   this</span><span style="color:#24292E;">.breed</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">breed;</span></span>
<span class="line"><span style="color:#005CC5;">   this</span><span style="color:#24292E;">.color</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">color;</span></span>
<span class="line"><span style="color:#005CC5;">   this</span><span style="color:#24292E;">.sex</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">sex;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> theDog </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Dog</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Gabby&quot;</span><span style="color:#24292E;">,</span><span style="color:#032F62;">&quot;Lab&quot;</span><span style="color:#24292E;">,</span><span style="color:#032F62;">&quot;chocolate&quot;</span><span style="color:#24292E;">,</span><span style="color:#032F62;">&quot;female&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>如果当前的对象调用了 toString() 方法，它将会返回从 Object 继承下来的 toString() 方法的返回默认值：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">theDog.</span><span style="color:#6F42C1;">toString</span><span style="color:#24292E;">(); </span><span style="color:#6A737D;">// 返回 [object Object]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>下面的代码中定义了一个叫做 dogToString() 的方法来覆盖默认的 toString() 方法。这个方法生成一个 &quot;property = value&quot; 形式的 字符串，该字符串包含了当前对象的 name， breed，color 和 sex的值。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">Dog</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">prototype</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">toString</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> function</span><span style="color:#6F42C1;"> dogToString</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#D73A49;">  var</span><span style="color:#24292E;"> ret </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &quot;Dog &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#005CC5;"> this</span><span style="color:#24292E;">.name </span><span style="color:#D73A49;">+</span><span style="color:#032F62;"> &quot; is a &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#005CC5;"> this</span><span style="color:#24292E;">.sex </span><span style="color:#D73A49;">+</span><span style="color:#032F62;"> &quot; &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#005CC5;"> this</span><span style="color:#24292E;">.color </span><span style="color:#D73A49;">+</span><span style="color:#032F62;"> &quot; &quot;</span><span style="color:#D73A49;"> +</span><span style="color:#005CC5;"> this</span><span style="color:#24292E;">.breed;</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> ret;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>有了上面的这段代码之后，在上下文中任何时候使用 theDog ，JavaScript 都会自动调用 dogToString() 方法，并且返回下面的字符串内容：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Dog Gabby is a female chocolate Lab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="使用tostring-方法来检测对象类型" tabindex="-1">使用toString()方法来检测对象类型 <a class="header-anchor" href="#使用tostring-方法来检测对象类型" aria-label="Permalink to &quot;使用toString()方法来检测对象类型&quot;">​</a></h3><p>可以通过toString() 来获取每个对象的类型。为了每个对象都能通过 Object.prototype.toString() 来检测，需要以 Function.prototype.call() 或者 Function.prototype.apply() 的形式来调用，把需要检测的对象作为第一个参数传入。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> toString </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> Object</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">prototype</span><span style="color:#24292E;">.toString;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">toString.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">new</span><span style="color:#24292E;"> Date); </span><span style="color:#6A737D;">// [object Date]</span></span>
<span class="line"><span style="color:#24292E;">toString.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">new</span><span style="color:#24292E;"> String); </span><span style="color:#6A737D;">// [object String]</span></span>
<span class="line"><span style="color:#24292E;">toString.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(Math); </span><span style="color:#6A737D;">// [object Math]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//Since JavaScript 1.8.5</span></span>
<span class="line"><span style="color:#24292E;">toString.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">undefined</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// [object Undefined]</span></span>
<span class="line"><span style="color:#24292E;">toString.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">null</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// [object Null]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,27)])])}const u=a(e,[["render",o]]);export{b as __pageData,u as default};
